    const prioritySelect = row => row.match(/<select id="task-priority-\d+"[^>]*>[\s\S]*?<\/select>/)[0];
    const options = row => [...prioritySelect(row).matchAll(/<option( selected)?>([^<]+)<\/option>/g)]
