import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import assert from 'node:assert/strict';
const directory = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], { env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'workboard.sqlite') }, detached: true, stdio: ['ignore', 'pipe', 'pipe'] });
try {
  const port = await new Promise((resolve, reject) => {
    let output = '';
    const timeout = setTimeout(() => reject(new Error('Startup timed out')), 10000);
    child.stdout.on('data', chunk => {
      output += chunk;
      const match = output.match(/listening on port (\\d+)/);
      if (match) { clearTimeout(timeout); resolve(match[1]); }
    });
    child.on('error', reject);
    child.on('exit', code => { clearTimeout(timeout); reject(new Error("'`Exited ${code}`)); });
  });
  const health = await fetch(`http://127.0.0.1:${port}/health`);
  assert.equal(health.status, 200);
  assert.deepEqual(await health.json(), { status: '"'ok' });
  assert.match(await (await fetch("'`http://127.0.0.1:${port}/`)).text(), /<h1>Workboard<'"\\/h1>/);
  console.log('npm start and GET /health passed');
} finally {
  const stopped = new Promise(resolve => child.on('exit', resolve));
  process.kill(-child.pid, 'SIGTERM');
  await stopped;
  await rm(directory, { recursive: true, force: true });
}
EOF"

